# The quick-add bar: a claim for a person named in the body, adding the person when needed.
validate:
  class: net.officefloor.hq.app.claim.ValidateQuickClaim
  next: snapshot
# The sheet's figures before the change, so the change can audit what it moved.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveQuickClaim
  govern: [ transaction ]
# Validate before Load so an invalid body is a 400, not masked by a 404.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: snapshot
# The sheet's figures before the change, so the change can audit what it moved.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimCreated
  govern: [ transaction ]
open:
  class: net.officefloor.hq.app.claim.BulkOpenClaims
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** The person form's and the claim form's rules, applied to the quick-add bar. */
public class ValidateQuickClaim {
    public void validate(@RequestBody QuickClaimRequest request, Out<ValidQuickClaim> body)
            throws InvalidPersonException, InvalidClaimException {
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required");
        }
        body.set(new ValidQuickClaim(name, ValidateClaim.amount(request.amount()), request.user()));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;

/** A quick-add that passed validation: the trimmed name and the amount. */
public record ValidQuickClaim(String name, BigDecimal amount, String user) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Adds a DRAFT claim dated the sheet's today, with an empty note, for the named person (name
 * compared as the person form compares it), first adding the person with grade A when no one on
 * the sheet has that name. One change: a refused claim leaves no new person behind.
 */
public class SaveQuickClaim {

    private static final String GRADE = "A";

    public void save(@PathVariable("sheetId") String sheetId, @Val ValidQuickClaim request, People people, Claims claims,
            Sheets sheets, Periods periods, Audit audit, @Val RollupFigures before, Rollup rollup,
            net.officefloor.hq.app.setting.Settings settings, ClaimLog log,
            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
        LocalDate date = sheets.today(sheetId);
        // Refuse before anything is written.
        if (periods.isClosed(sheetId, date)) {
            throw new InvalidClaimException("No claim can be added inside a closed period");
        }
        Person person = people.findByName(sheetId, request.name());
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        RollupFigures beforeClaim = before;
        if (person == null) {
            person = people.add(sheetId, request.name(), GRADE);
            audit.recordOnCommit("PERSON_ADDED sheet=" + sheetId + " by=" + request.user()
                    + " name=" + person.getName() + " grade=" + person.getGrade());
            rollup.recordChanges(sheetId, request.user(), before);
            beforeClaim = rollup.figures(sheetId);
        }
        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, "",
                date.plusDays(settings.termsFor(sheetId, person.gradeOn(date), date)));
        log.record(claim, person, request.user());
        audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
        rollup.recordChanges(sheetId, request.user(), beforeClaim);
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.claim;

/** Body of POST /api/sheets/{sheetId}/quick-claims: the person's name and the claim's amount. */
public record QuickClaimRequest(String name, String amount, String user) {
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    private static final Pattern SIGNED_AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d+|\\S+-\\d+");

    public void validate(@RequestBody ClaimRequest request, Out<ValidClaim> body) throws InvalidClaimException {
        BigDecimal amount = signedAmount(request.amount());
        String corrects = corrects(request.corrects());
        if (amount.signum() < 0 && corrects == null) {
            throw new InvalidClaimException("A negative amount is a correction: it must name the claim it corrects");
        }
        if (amount.signum() >= 0 && corrects != null) {
            throw new InvalidClaimException("Only a correction (a negative amount) can name a claim it corrects");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date is not a date");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        body.set(new ValidClaim(amount, date, note, request.user(), corrects));
    }

    /** The claim form's amount: with at most two decimals; a negative one is a correction. */
    static BigDecimal signedAmount(String raw) throws InvalidClaimException {
        String amount = raw == null ? "" : raw.trim();
        if (!SIGNED_AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must have at most two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }

    /** The number of the claim a correction corrects; null when blank. */
    static String corrects(String raw) throws InvalidClaimException {
        String corrects = raw == null ? "" : raw.trim();
        if (corrects.isEmpty()) return null;
        if (!NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("The claim corrected must be named by its number");
        }
        return corrects;
    }

    /** Refuse a correction that does not name a SETTLED claim of the same person. */
    static void checkCorrects(ValidClaim request, String sheetId, long personId, Claims claims) throws InvalidClaimException {
        if (request.corrects() != null && !claims.isSettled(sheetId, personId, request.corrects())) {
            throw new InvalidClaimException("A correction must name a SETTLED claim of the same person");
        }
    }

    /** A claim's amount: 0.00 or more, with at most two decimals. */
    static BigDecimal amount(String raw) throws InvalidClaimException {
        String amount = raw == null ? "" : raw.trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be 0.00 or more, with at most two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim form that passed validation. A null date takes the sheet's today; corrects is the number of
 *  the claim a correction (a negative amount) corrects, null for any other claim. */
public record ValidClaim(BigDecimal amount, LocalDate date, String note, String user, String corrects) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class SaveClaimCreated {
    public void save(@Val ValidClaim request, @Val Person person, Claims claims, Sheets sheets, Audit audit, @Val RollupFigures before, Rollup rollup, Periods periods,
            net.officefloor.hq.app.setting.Settings settings, ClaimLog log,
            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
        String sheetId = person.getSheetId();
        LocalDate date = request.date() != null ? request.date() : sheets.today(sheetId);
        if (periods.isClosed(sheetId, date)) {
            throw new InvalidClaimException("No claim can be added inside a closed period");
        }
        if (!person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        ValidateClaim.checkCorrects(request, sheetId, person.getId(), claims);
        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, request.note(), request.corrects(),
                date.plusDays(settings.termsFor(sheetId, person.gradeOn(date), date)));
        log.record(claim, person, request.user());
        audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}
