import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { claimsKey, type Claim } from '../claims/useClaims';
import { peopleKey } from './usePeople';

// The quick-add bar on the people list: a name and an amount make a DRAFT claim dated the sheet's
// today, with an empty note, for the person of that name (case and outer spaces ignored) — adding
// the person with grade A first when no one on the sheet has it. The person form's and the claim
// form's rules apply; a refusal adds no one and nothing.
export function QuickAdd() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();

  const add = useMutation({
    mutationFn: (body: { name: string; amount: string }) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/quick-claims`, { ...body, user }),
    onSuccess: () => {
      setName('');
      setAmount('');
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });

  const changed = (set: (v: string) => void) => (v: string) => {
    set(v);
    add.reset();
  };

  return (
    <form
      data-testid="quick-add"
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          add.reset();
          return add.mutateAsync({ name: name.trim(), amount: amount.trim() });
        });
      }}
    >
      <input data-testid="quick-name" value={name} placeholder="Name" onChange={(e) => changed(setName)(e.target.value)} />{' '}
      <input
        data-testid="quick-amount"
        value={amount}
        placeholder="Amount"
        inputMode="decimal"
        onChange={(e) => changed(setAmount)(e.target.value)}
      />{' '}
      <button type="submit" data-testid="quick-submit">Quick add</button>
      {add.isError && (
        <span data-testid="quick-error" role="alert"> Could not add: a name is required, the amount must be 0.00 or more, with at most two decimals, and no claim can be dated inside a closed period.</span>
      )}
    </form>
  );
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
